// n8n Code Node

function extractJsonFromText(text) {

  if (!text) return null;

  // Buscar bloque ```json ... ```
  const blockMatch = text.match(/```json\s*([\s\S]*?)\s*```/i);

  if (blockMatch) {
    return JSON.parse(blockMatch[1]);
  }

  // Buscar cualquier JSON en el texto
  const jsonMatch = text.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    return JSON.parse(jsonMatch[0]);
  }

  throw new Error("No JSON object found in text");
}


// Generador de case_number
function generateCaseNumber(length = 15) {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  let result = "";

  for (let i = 0; i < length; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }

  return result;
}


const results = [];

for (const item of items) {

  const rawText =
    item.json.text ||
    item.json.body ||
    item.json.message ||
    item.json.output ||
    item.json.response ||
    "";

  try {

    const data = extractJsonFromText(rawText);

    const now = new Date();
    const iso = now.toISOString();

    const submissionDate = iso.split("T")[0];
    const submissionTime = iso.split("T")[1].split(".")[0];
    const anonymousValue = (data.anonymous || "").toLowerCase() === "yes" ? "TRUE" : "FALSE";

    const cleanOutput = {
      case_number: generateCaseNumber(),
      fullName: data.fullName || "",
      email: data.email || "",
      phone: data.phone || "",
      incidentDate: data.incidentDate || "",
      incidentTime: data.incidentTime || "",
      healthFacility: data.healthFacility || "",
      department: data.department || "",
      complaintDetails: data.complaintDetails || "",
      anonymous: anonymousValue || "",
      followUp: data.followUp || "",
      personalId: data.personalId || "",
      submissionDate: submissionDate,
      submissionTime: submissionTime
    };

    results.push({
      json: cleanOutput
    });

  } catch (error) {

    results.push({
      json: {
        error: "JSON extraction failed",
        details: error.message,
        receivedText: rawText
      }
    });

  }
}

return results;
